"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[31003],{73120:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CharacterCollisionService","desc":"Places every BasePart of every player character into the `Character` collision\\ngroup (see CollisionGroups). This is what lets physics projectiles\\n(`WeaponProjectile`) and dropped materials (`DroppedMaterial`) pass through\\nplayers while still colliding with world geometry \u2014 all three previously shared\\nthe `Default` group, so they could not be told apart by the physics solver.\\n\\nParts that stream in after spawn (R15 limbs, accessories) are caught via\\n`DescendantAdded`; the connection is owned by a per-character Janitor torn down\\nwhen the character is destroyed.","realm":["Server"],"source":{"line":16,"path":"src/ServerScriptService/CharacterCollisionService.server.luau"}}')}}]);